INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67478, 'spa', 'Creyente pionero', 'El saludo afectuoso de Pablo identifica a Epaíneto como un creyente pionero. El nombre personal aparece transliterado en diversas lenguas (español ''Epaíneto'', francés ''Épaïnète'', alemán ''Epainetus''), conservando la forma griega. Su designación como ''primicias'' sugiere tanto prioridad temporal como devoción especial, convirtiéndolo en una figura fundacional en la expansión del evangelio en su región.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67479, 'spa', 'Alabar, elogiar', 'Expresar aprobación, elogio o alabanza hacia una persona o su conducta. Las seis apariciones neotestamentarias comparten este significado central, aunque la fuerza pragmática varía desde el elogio sincero (Romanos 15:11, citando el Salmo 117:1, ''Alabad al Señor, todas las naciones'') hasta la ironía punzante (1 Corintios 11:17, 22, donde Pablo niega su alabanza). El español ''alabo'' refleja fielmente el sentido de reconocimiento público.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67483, 'spa', 'Alabanza, elogio o aprobación', 'Alabanza, elogio o aprobación: el reconocimiento de mérito o excelencia, ya sea otorgado por Dios, por las autoridades civiles o por la comunidad de fe. Alabanza divina: la verdadera circuncisión recibe su alabanza de Dios, no de los hombres (Ro 2:29); la obra de cada creyente recibirá reconocimiento de Dios en el retorno de Cristo (1 Co 4:5). Alabanza cívica: el gobernante elogia a quienes hacen el bien (Ro 13:3; 1 P 2:14). En el uso doxológico de Efesios, la elección y la herencia son para alabanza de la gloria de Dios (Ef 1:6, 12, 14). Fil 4:8 insta a reflexionar sobre todo lo digno de alabanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67484, 'spa', 'Levantar o alzar fisicamente algo, tipicamente los ojos, las manos o la cabeza, ', 'Levantar o alzar fisicamente algo, tipicamente los ojos, las manos o la cabeza, en un gesto corporal concreto. Es el uso dominante en el NT: Jesus alzando sus ojos (Lc 6:20; Jn 4:35; 6:5; 11:41; 17:1), el hombre rico alzando sus ojos en el Hades (Lc 16:23), y los discipulos alzando sus ojos en la Transfiguracion (Mt 17:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67487, 'spa', 'Izar o levantar una vela en contexto nautico, aplicacion tecnica especializada d', 'Izar o levantar una vela en contexto nautico, aplicacion tecnica especializada del significado basico de levantar. En Hch 27:40, durante el dramatico relato del naufragio, los marineros ''izaron la vela de proa'' (ἐπάραντες τὸν ἀρτέμωνα) para dirigirse hacia la costa. Esta unica aparicion muestra cuan naturalmente el verbo se adapta a contextos especificos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67488, 'spa', 'Ser levantado o elevado pasivamente, describiendo la elevacion corporal por pode', 'Ser levantado o elevado pasivamente, describiendo la elevacion corporal por poder divino. En Hch 1:9 Cristo ''fue levantado'' (ἐπήρθη) ante los ojos de los discipulos mientras una nube lo recibia: la Ascension misma. La voz pasiva distingue este sentido de todos los demas: el sujeto no levanta sino que es levantado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67490, 'spa', 'Levantar o alzar la voz, extension figurada donde el objeto pasa de una parte de', 'Levantar o alzar la voz, extension figurada donde el objeto pasa de una parte del cuerpo al habla. En Hch 14:11 los licaonios ''alzaron la voz'' llamando a Bernabe Zeus, y en Hch 22:22 la multitud ''alzo su voz'' pidiendo la muerte de Pablo. Es una extension natural del gesto fisico de levantar aplicada al volumen vocal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67491, 'spa', 'Exaltarse o elevarse a si mismo en orgullo o arrogancia, usado en voz media para', 'Exaltarse o elevarse a si mismo en orgullo o arrogancia, usado en voz media para indicar autoexaltacion reflexiva. Pablo lo emplea dos veces en 2 Corintios: toda ''altivez que se levanta'' (ἐπαιρόμενον) contra el conocimiento de Dios (10:5), y el falso apostol que ''se enaltece'' sobre la comunidad (11:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67495, 'spa', 'Avergonzarse de algo o sentir deshonra respecto a una persona, un mensaje o una ', 'Avergonzarse de algo o sentir deshonra respecto a una persona, un mensaje o una lealtad que se está llamado a confesar abiertamente. Jesús advierte que quienes se avergüencen de él y de sus palabras enfrentarán una vergüenza recíproca en el regreso del Hijo del Hombre (Mr 8:38; Lc 9:26). Pablo declara con valentía que no se avergüenza del evangelio (Ro 1:16) y exhorta a Timoteo a la misma firmeza (2 Ti 1:8, 12). Se elogia a Onesíforo por no haberse avergonzado de las cadenas de Pablo (2 Ti 1:16). Dios mismo no se avergüenza de ser llamado Dios de los fieles (Heb 2:11; 11:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67503, 'spa', 'Seguir de cerca', 'Seguir estrechamente o acompañar, ya sea en sentido literal o figurado. En Marcos 16:20 las señales milagrosas ''acompañan'' la predicación confirmando la palabra. En 1 Timoteo 5:10 el verbo describe la dedicación perseverante a las buenas obras, mientras que en 5:24 se refiere a pecados que persiguen a ciertas personas hasta el juicio. Primera de Pedro 2:21 llama a los creyentes a seguir las huellas de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67504, 'spa', 'Escucha divina activa', 'Pablo aplica el oráculo de Isaías al momento presente de la salvación. El español ''te escuché'', el francés ''écouter'' y el alemán ''erhören'' captan la dimensión responsiva del oír divino. No se trata de recepción auditiva pasiva, sino del compromiso activo de Dios con la petición humana, ahora cumplido en Cristo. El aoristo marca un momento definitivo de atención y favor divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67505, 'spa', 'Escucha atenta y cautivada', 'Lucas retrata a los prisioneros como audiencia de una adoración nocturna. El español ''escuchaban'' y la forma griega misma enfatizan la audición atenta. Esta escena de oyentes cautivos prepara el escenario para el terremoto que sacudirá la prisión y conducirá a la conversión del carcelero. El verbo implica algo más que oír casualmente: una atención absorta ante un acontecimiento extraordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67506, 'spa', 'Marcador temporal', 'Todas las traducciones lo vierten directamente como marcador de tiempo: en español «cuando», en francés «quand». Mateo 2:8 presenta a Herodes diciendo «cuando lo encontréis, avisadme». Lucas 11:22 describe el momento «cuando uno más fuerte lo ataca y lo vence». Lucas 11:34 habla del efecto «cuando tu ojo está sano». La conjunción marca coincidencia o secuencia temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67507, 'spa', 'Obligación indispensable', 'El Concilio de Jerusalén identifica una lista breve de requisitos ''necesarios'' para los creyentes gentiles. La evidencia multilingüe (español ''necesarias'', alemán preservando la misma forma) converge en la idea de obligación o compulsión. No son sugerencias sino mínimos vinculantes: abstenerse de lo sacrificado a ídolos, de sangre, de lo estrangulado y de la inmoralidad sexual. El adverbio marca estos preceptos como indispensables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67508, 'spa', 'Navegar o volver', 'Las traducciones reflejan lenguaje náutico: en español «navegar, alejarse, volviendo», en francés «avancer». Mateo 21:18 describe a Jesús «volviendo» a la ciudad. Lucas 5:3 relata que Jesús pidió a Simón «apartarse un poco de tierra», mientras que 5:4 contiene el célebre mandato: «Boga mar adentro y echad vuestras redes». El verbo expresa movimiento marítimo desde o hacia la orilla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67509, 'spa', 'Refuerzo de lo conocido', 'El uso paulino reconoce que la iglesia ya posee la verdad sobre la cual escribe. El español ''recordándoos'', el francés ''rappeler'' y el alemán ''erinnern'' captan el acto de traer a la mente lo previamente conocido. No es instrucción original sino repetición estratégica para dar énfasis y claridad, coherente con el papel de Pablo como apóstol que escribe ''con cierta osadía en algunos puntos'' para reforzar enseñanzas esenciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67513, 'spa', 'Corrección escritural', 'Pablo enumera la corrección como una de las funciones de la Escritura inspirada. No se trata de un castigo sino de una realineación constructiva: enderezar el pensamiento o la conducta torcida hacia el camino correcto. La Escritura actúa como instrumento tanto diagnóstico (reprensión) como terapéutico (corrección), capacitando al creyente para toda buena obra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67514, 'spa', 'Encima, sobre, por encima de — indicando posicion espacial donde algo esta mas a', 'Encima, sobre, por encima de — indicando posicion espacial donde algo esta mas alto que otra cosa o descansando sobre ella. La estrella se detuvo encima del lugar donde estaba el nino (Mt 2:9), una ciudad puesta sobre un monte no puede esconderse (Mt 5:14), y la autoridad se ejerce sobre ciudades (Lc 19:17, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67516, 'spa', 'Mas de, en exceso de — usado comparativamente para indicar una cantidad o grado ', 'Mas de, en exceso de — usado comparativamente para indicar una cantidad o grado que excede una medida indicada. En Mc 14:5 el ungueento pudo haberse vendido ''por mas de'' trescientos denarios, y en 1 Co 15:6 el Cristo resucitado aparecio a ''mas de'' quinientos hermanos a la vez. Muestra la transicion de lo espacial a lo cuantitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67518, 'spa', 'Socorrer al necesitado', 'Los traductores emplean consistentemente términos de ayuda: en español «socorra, socorrió». Las tres apariciones se hallan en 1 Timoteo 5, relativas al apoyo a las viudas: una mujer que ha «socorrido» a los afligidos (5:10), si algún creyente tiene viudas a quienes «socorrer» (5:16, primer uso), y la exhortación a «que ella las socorra» para no gravar a la iglesia (5:16, segundo uso).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67520, 'spa', 'Morada o habitación', 'Pedro aplica la imprecación del salmista al destino de Judas. La maldición de desolación transforma la residencia del traidor en una ruina vacía, símbolo del juicio divino. Este acto establece la necesidad de elegir un reemplazante que ocupe el lugar de ministerio que Judas abandonó al entregar al Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67521, 'spa', 'Al dia siguiente, al otro dia', 'Al dia siguiente, al otro dia. Adverbio temporal que avanza el tiempo narrativo exactamente un dia. Aparece de manera prominente en el Evangelio de Juan para secuenciar los primeros dias del ministerio publico de Jesus (Jn 1:29, 35, 43) y en Hechos para rastrear los viajes de Pablo (Hch 10:9, 23; 14:20; 20:7; 21:8; 22:30; 25:6). En Mt 27:62 marca el dia despues de la crucifixion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67522, 'spa', 'En flagrante delito', 'Los acusadores subrayan la naturaleza innegable de la culpa de la mujer. La expresión indica detección inmediata e irrefutable del delito. No obstante, Jesús transforma la escena: en vez de condenar según la evidencia, confronta la hipocresía de quienes acusan y extiende misericordia, elevando el relato de lo jurídico a lo redentor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67523, 'spa', 'Nombre propio', 'El nombre aparece de forma idéntica en todos los idiomas como nombre propio: Epafras en español e inglés. Colosenses 1:7 lo presenta como quien enseñó el evangelio a los colosenses, mientras que 4:12 lo describe «luchando siempre por vosotros en sus oraciones» para que permanezcan firmes y maduros en la voluntad de Dios. Filemón 23 lo incluye entre los compañeros de prisión de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67524, 'spa', 'Espumar vergüenza', 'Judas emplea una vívida imagen náutica para retratar a los maestros heréticos. Así como las olas tempestuosas revuelven y sacan a flote la basura del fondo, estos falsos maestros manifiestan públicamente sus obras y doctrinas vergonzosas. El verbo transmite una exposición violenta e incontrolable de la corrupción interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67527, 'spa', 'Conjunción que cumple funciones tanto causales (''ya que, porque'') como contrafac', 'Conjunción que cumple funciones tanto causales (''ya que, porque'') como contrafactuales (''de lo contrario''). El sentido causal fundamenta una inferencia en un hecho reconocido: ''ya que lo juzgaste malvado'' (Mt 18:32), ''ya que no conozco varón'' (Lc 1:34), ''ya que es justo ante Dios retribuir'' (2 Ts 1:6). El sentido contrafactual introduce lo que necesariamente seguiría si una condición no se cumpliera, un recurso argumentativo frecuente en Pablo y Hebreos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67532, 'spa', 'Conjunción causal que significa ''puesto que'', ''porque'', ''ya que''', 'Conjunción causal que significa ''puesto que'', ''porque'', ''ya que'': introduce una razón o fundamento explicativo para la cláusula principal. Abarca nueve de las diez apariciones en el NT. Pablo la emplea para fundamentar argumentos teológicos (1 Co 1:21-22; 14:16), y también introduce razonamientos prácticos en la narrativa (Lc 11:6; Hch 13:46; 15:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67534, 'spa', 'Conjunción temporal que significa ''cuando'' o ''después que'', introduciendo una cl', 'Conjunción temporal que significa ''cuando'' o ''después que'', introduciendo una cláusula de tiempo que marca la conclusión de un evento precedente. Aparece una sola vez en Lc 7:1, haciendo la transición del Sermón del Llano al relato del siervo del centurión. El cambio del español ''puesto que'' (causal) a ''después que'' (temporal) en este versículo marca claramente la función temporal en lugar de la lógica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67535, 'spa', 'Conjunción causal enfática', 'La apertura de Lucas señala su conocimiento de las tradiciones evangélicas anteriores. No contradice los relatos previos sino que se apoya en ellos con su propia investigación ordenada. La conjunción establece la premisa causal: puesto que ya existen testimonios de testigos oculares, Lucas emprende su narrativa con fundamento sólido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67537, 'spa', 'Introducción sustitutiva', 'El autor de Hebreos contrasta la incapacidad del antiguo pacto para perfeccionar a los adoradores con la introducción de un acceso superior a Dios. No se trata de una mera añadidura, sino de un reemplazo: el sacerdocio levítico y sus regulaciones quedan abolidos, y una esperanza mejor es instaurada mediante Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67538, 'spa', 'Adverbio temporal-secuencial que significa ''despues, luego, a continuacion'', usa', 'Adverbio temporal-secuencial que significa ''despues, luego, a continuacion'', usado para marcar etapas sucesivas en una narrativa, argumento o enumeracion. Particularmente prominente en las listas paulinas: apariciones de la resurreccion (1 Co 15:5-8), secuencia escatologica (1 Co 15:23-24, 46) y dones espirituales clasificados (1 Co 12:28). Tambien funciona en transiciones narrativas (Lc 16:7; Jn 11:7) y argumentacion logica (He 7:2, 27; Stg 3:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67539, 'spa', 'Más allá espacial', 'En el discurso de Esteban, este término aparece al citar el juicio profético contra la idolatría de Israel. Dios enviará al pueblo rebelde más allá de Babilonia, hasta los confines más remotos, como castigo. No se trata de cruzar simplemente una frontera, sino de un destierro a las regiones más distantes, simbolizando la separación total de la tierra prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67540, 'spa', 'Esfuerzo hacia adelante', 'Pablo emplea una metáfora atlética para describir su vida cristiana. La forma participial capta una acción continua: estirarse constantemente hacia adelante mientras se olvida el pasado. No es una actitud pasiva sino un esfuerzo pleno y sostenido, prosiguiendo hacia la meta del supremo llamamiento de Dios en Cristo Jesús con dedicación total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67542, 'spa', 'Prenda exterior', 'En la narrativa de la resurrección según Juan, este detalle revela la reverente premura de Pedro. Su gesto de vestirse antes de saltar al agua muestra tanto urgencia como decoro: se lanza al mar pero primero se viste apropiadamente. La prenda exterior señala respeto hacia el Señor, incluso en medio de la prisa por alcanzarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67543, 'spa', 'Venir sobre, llegar o sobrevenir', 'Venir sobre, llegar o sobrevenir: abarca la visitación divina, el advenimiento de eventos y la llegada física. El Espíritu Santo ''viene sobre'' María (Lc 1:35) y el poder ''viene sobre'' los discípulos (Hch 1:8), representando un advenimiento sobrenatural. Terrores escatológicos ''sobrevienen'' al mundo (Lc 21:26; Stg 5:1), y un adversario más fuerte ''viene sobre'' el hombre armado (Lc 11:22). Las formas participiales expresan movimiento desde un lugar de origen, como los judíos que ''vinieron de'' Antioquía (Hch 14:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67552, 'spa', 'preguntar, interrogar', 'Preguntar o interrogar a alguien directamente, ya sea buscando información, poniendo a prueba al interlocutor o realizando un interrogatorio formal. En Mt 22:35 un legista pregunta a Jesús para ponerlo a prueba; en Mr 9:32 los discípulos temen preguntarle sobre su predicción de la pasión; en Mt 27:11 Pilato lo interroga judicialmente. Las 56 apariciones convergen en este único sentido de indagación dirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67568, 'spa', 'Petición o compromiso', 'La compleja frase de Pedro ha generado abundante interpretación. ¿Significa ἐπερώτημα el compromiso de fidelidad del bautizado o su apelación pidiendo la purificación divina? El contexto más amplio sugiere que el bautismo involucra tanto un compromiso consciente como una respuesta divina. Se trata de una transacción pactual, no de un simple lavamiento ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67569, 'spa', 'Prestar atención', 'Prestar atención cuidadosa, notar, fijar la mente en algo. Jesús notó cómo los invitados escogían los lugares de honor (Luc 14:7), el cojo prestó atención a Pedro y Juan esperando algo (Hch 3:5), y Pablo exhorta a Timoteo a prestar atención a sí mismo y a su enseñanza (1 Tim 4:16). Las traducciones presta-atención y notando confirman el enfoque cognitivo de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67570, 'spa', 'Ultrajar y maltratar', 'Las traducciones multilingües enfatizan la agresión verbal y la acción hostil: maltratar, ultrajar, injuriar. En Mateo 5:44 y Lucas 6:28, Jesús manda orar por «los que os maltratan», como parte radical de la ética del amor al enemigo. En 1 Pedro 3:16, Pedro exhorta a vivir con integridad para que «quienes ultrajan vuestra buena conducta en Cristo» queden avergonzados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67571, 'spa', 'sobre/encima de (espacial)', 'Contacto físico con la superficie superior de algo; posado sobre, apoyado en.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67573, 'spa', 'en/junto a (ubicación)', 'Ubicación en un lugar específico o en las inmediaciones de algo; cerca de, en presencia de.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67585, 'spa', 'hacia/dirección', 'Movimiento en dirección a un objetivo o meta; rumbo a, con destino a.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67587, 'spa', 'con base en', 'El fundamento, razón o evidencia sobre la cual algo se apoya; basado en, en virtud de.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67588, 'spa', 'acerca de/sobre', 'El tema, asunto o materia de la que se habla o trata; concerniente a, respecto a.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67589, 'spa', 'contra/oposición', 'Hostilidad, ataque u oposición dirigida hacia alguien o algo; en contra de.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67612, 'spa', 'Subir, embarcar, pisar', 'Pisar, embarcar, poner pie sobre algo o montar: abarca tanto el acto de abordar una embarcación para un viaje marítimo como el de llegar a un destino entrando físicamente en él. En Hechos, Lucas lo usa repetidamente para los viajes misioneros de Pablo: embarcarse en Troas (Hechos 21:2), poner pie en la provincia de Asia (Hechos 20:18) y desembarcar en Cesarea (Hechos 25:1). Mateo 21:5, citando Zacarías 9:9, emplea el participio para describir a Jesús montado sobre un pollino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67617, 'spa', 'Echar mano a alguien con intencion hostil, tipicamente para arrestar o prender p', 'Echar mano a alguien con intencion hostil, tipicamente para arrestar o prender por la fuerza. Es el uso dominante del NT, apareciendo diez veces en contextos de persecucion e intento de arresto. En Mt 26:50 la multitud echa mano a Jesus en Getsemani, y en Lc 21:12 Jesus advierte a sus discipulos que les echaran mano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67619, 'spa', 'Poner, colocar o echar algo sobre una superficie o persona en un sentido no host', 'Poner, colocar o echar algo sobre una superficie o persona en un sentido no hostil y practico. Jesus habla de que nadie pone un remiendo nuevo en vestido viejo (Mt 9:16; Lc 5:36), los discipulos echan sus mantos sobre el pollino (Mc 11:7), y en Lc 9:62 nadie que pone su mano en el arado y mira atras es apto para el reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67620, 'spa', 'De fuerzas naturales, particularmente olas, golpeando o rompiendo contra algo', 'De fuerzas naturales, particularmente olas, golpeando o rompiendo contra algo. En Mc 4:37 se levanta una gran tempestad y las olas golpeaban contra el barco de manera que ya se llenaba. Captura la fuerza violenta y repetitiva del mar, sentido unico de esta unica aparicion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67624, 'spa', 'Uso intransitivo o reflexivo llamativo que significa poner la mente en algo y qu', 'Uso intransitivo o reflexivo llamativo que significa poner la mente en algo y quebrantarse emocionalmente. En Mc 14:72, despues de que el gallo canta por segunda vez, Pedro — variadamente traducido como ''pensando en ello'' o ''habiendo roto en llanto'' — lloro amargamente. Enfatiza el momento cognitivo de reflexion que desencadena el colapso emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67625, 'spa', 'Uso impersonal o medio que significa ''corresponder a alguien'', refiriéndose a la', 'Uso impersonal o medio que significa ''corresponder a alguien'', refiriéndose a la porcion de una herencia o propiedad que pertenece a alguien. En Lc 15:12 el hijo menor pide la parte de la hacienda que le ''corresponde''. Captura el sentido distributivo, casi juridico, de lo que se debe o se asigna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67628, 'spa', 'Ser carga económica', 'Las traducciones utilizan consistentemente lenguaje de carga y peso: ser carga, abrumar, gravar. En 2 Corintios 2:5, Pablo maneja con delicadeza un caso de disciplina, diciendo «para no abrumaros a todos». En 1 Tesalonicenses 2:9 y 2 Tesalonicenses 3:8, recuerda a las iglesias que trabajaba día y noche «para no ser carga a ninguno de vosotros» mientras predicaba el evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67629, 'spa', 'Montar sobre animal', 'Las evidencias multilingües apuntan a montar y colocar encima: montar, poner, hacer subir. Lucas 10:34 describe la compasión del samaritano al «ponerlo sobre su propia cabalgadura» para llevarlo a un lugar seguro. Lucas 19:35 narra cómo los discípulos «hicieron montar a Jesús» sobre el pollino en la entrada triunfal. Hechos 23:24 muestra a los oficiales romanos proveyendo monturas para «hacer montar a Pablo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67630, 'spa', 'Mirar con atención', 'Las traducciones emplean términos de ver y considerar: mirar, poner los ojos en, contemplar. Lucas 1:48 contiene el cántico de María: «ha mirado la humilde condición de su sierva», expresando la atención graciosa de Dios hacia los humildes. Lucas 9:38 recoge la súplica desesperada de un padre: «te ruego que mires a mi hijo». Santiago 2:3 critica el favoritismo: «si miráis con agrado» al de vestido elegante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67631, 'spa', 'Remiendo de tela', 'Parche o remiendo de tela aplicado para reparar una prenda, usado exclusivamente en la parábola de Jesús sobre el paño nuevo en vestido viejo. La imagen es vívida y doméstica. Mateo 9:16, Marcos 2:21 y Lucas 5:36 emplean este sustantivo en el mismo contexto didáctico, donde la incompatibilidad del remiendo nuevo con la tela vieja ilustra la novedad radical del mensaje de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67632, 'spa', 'Conspiración hostil', 'Complot o conspiración tramada contra alguien, con implicaciones de secretismo y coordinación maliciosa. Todas las apariciones neotestamentarias involucran maquinaciones contra el apóstol Pablo: el complot de Damasco (Hechos 9:24), la conspiración en Grecia (20:3), las continuas asechanzas judías (20:19) y la emboscada reportada a Claudio Lisias (23:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67633, 'spa', 'Matrimonio por levirato', 'Los saduceos invocan el matrimonio por levirato para cuestionar la doctrina de la resurrección. Este verbo especializado designa una institución jurídica específica: la obligación del hermano sobreviviente de engendrar descendencia en nombre de su hermano fallecido. El acertijo de los siete hermanos que se casan sucesivamente con la misma mujer busca reducir al absurdo la creencia en la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67634, 'spa', 'Terrenal, de la tierra', 'Perteneciente o propio de la tierra en contraposición al cielo: describe cosas, personas o realidades que atañen al orden creado presente y no al ámbito divino o eterno. Jesús contrasta la enseñanza terrenal y la celestial en Juan 3:12. Pablo distingue cuerpos terrenales y celestiales en el discurso sobre la resurrección (1 Corintios 15:40) y describe el cuerpo presente como una ''tienda terrenal'' en 2 Corintios 5:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67638, 'spa', 'Surgir del viento', 'Lucas registra la llegada providencial de condiciones de viento favorables. Después de rodear hacia Regio, los marineros esperan las condiciones adecuadas. Cuando el viento del sur se levanta, aprovechan la oportunidad para navegar a Puteoli. La construcción de genitivo absoluto marca este acontecimiento como el factor determinante que posibilita la continuación del viaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67639, 'spa', 'conocer, llegar a conocer', 'conocer, llegar a conocer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67640, 'spa', 'reconocer, identificar', 'reconocer, identificar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67647, 'spa', 'conocer plenamente, conocer por completo', 'conocer plenamente, conocer por completo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67650, 'spa', 'ser conocido, ser reconocido', 'ser conocido, ser reconocido');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67652, 'spa', 'reconocer, aceptar como válido', 'reconocer, aceptar como válido');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67664, 'spa', 'Conocimiento profundo y experiencial, o reconocimiento, especialmente de Dios, d', 'Conocimiento profundo y experiencial, o reconocimiento, especialmente de Dios, de Cristo o de la verdad divina. El prefijo ἐπί intensifica el γνῶσις ordinario, apuntando a un trato completo en vez de una conciencia superficial. Pasajes clave incluyen Ro 1:28 (rechazo a reconocer a Dios), Ro 3:20 (conocimiento del pecado por la ley) y Ef 4:13 (conocimiento maduro del Hijo de Dios).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67666, 'spa', 'Inscripción identificativa', 'Inscripción o epígrafe escrito sobre un objeto físico con fines de identificación. Se usa para la inscripción en un denario romano que llevaba el nombre e imagen del César (Mat 22:20; Mar 12:16; Luc 20:24), y para el cargo escrito sobre Jesús crucificado que declaraba su supuesto delito (Mar 15:26; Luc 23:38). La uniformidad multilingüe — español inscripción, francés inscription — confirma su carácter técnico documental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67667, 'spa', 'Inscribir o grabar', 'Escribir sobre o inscribir texto en una superficie física o metafórica. Literalmente, el cargo fue inscrito sobre Jesús en la cruz (Mar 15:26) y un altar ateniense llevaba la inscripción ''Al Dios no conocido'' (Hch 17:23); los nombres de las doce tribus estaban inscritos en las puertas de la Jerusalén celestial (Ap 21:12). Figurada y teológicamente, Dios promete inscribir sus leyes en los corazones y mentes de su pueblo (Heb 8:10; 10:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67668, 'spa', 'Mostrar, exhibir, demostrar', 'Mostrar, exhibir o demostrar algo presentándolo visual o evidencialmente: exhibir para inspección o prueba. Jesús ordena a los fariseos mostrarle la moneda del tributo (Mateo 22:19) y se le muestran los edificios del templo (Mateo 24:1). Tras la sanidad, los leprosos reciben instrucción de mostrarse a los sacerdotes como evidencia de su limpieza (Lucas 17:14). En Jope, las viudas afligidas exhiben las túnicas confeccionadas por Dorcas (Hechos 9:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67673, 'spa', 'Añadir al pacto', 'Pablo emplea una metáfora legal para defender la justificación por fe. Así como los testamentos humanos permanecen inviolables una vez ejecutados, la promesa de Dios a Abraham se mantiene inalterada. La ley, llegada siglos después, no puede revisar los términos de la gracia. Este verbo subraya la imposibilidad de enmendar el pacto divino, apuntalando la supremacía de la promesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67674, 'spa', 'Dar, entregar en mano', 'Dar o entregar algo directamente a una persona, la transferencia interpersonal básica. Un padre entrega pan, pescado o un huevo a su hijo (Mt 7:9-10; Lc 11:11-12); Jesús recibe el rollo que le es entregado en mano (Lc 4:17). El español ''daba/dará/dieron'' refleja la acción directa de dar físicamente de una mano a otra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67676, 'spa', 'Entregar documento oficial', 'Entregar o hacer entrega formal de un documento u comunicación oficial. En Hechos 15:30, los delegados de Jerusalén ''entregaron'' la carta apostólica a la congregación de Antioquía. El español ''entregaron'' eleva el registro del dar casual a la transmisión oficial, destacando el peso autoritativo del documento entregado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67678, 'spa', 'Ceder al viento (náutico)', 'Sentido técnico náutico: ceder, dar paso ante la fuerza del viento o del mar. En Hechos 27:15, cuando la nave azotada por la tormenta no podía encarar el viento, la tripulación ''cedió'' y se dejó llevar. El español ''cediendo'' captura con precisión esta rendición marítima ante las fuerzas elementales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67680, 'spa', 'Ordenar lo pendiente', 'Pablo comisiona a Tito para completar la organización eclesial en Creta. Tito debe atender «lo que falta»: la tarea inconclusa de instalar liderazgo calificado en cada ciudad. El verbo implica tanto la corrección de problemas existentes como la culminación de un trabajo parcialmente realizado, llevando a las iglesias cretenses a un funcionamiento pleno y ordenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67681, 'spa', 'Puesta del sol', 'Pablo utiliza el ocaso como plazo moral. El mandato reconoce que la ira puede surgir, pero insiste en que no debe perdurar durante la noche. Cada puesta de sol debe ver alcanzada la reconciliación y resueltos los conflictos. El ritmo diario de la naturaleza se convierte en patrón para la salud relacional: que ningún rencor sobreviva al fin del día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67683, 'spa', 'Amable y condescendiente', 'Amable, indulgente, bondadoso — una disposición marcada por la razonabilidad llena de gracia y la voluntad de renunciar a derechos estrictos. En Fil 4:5 caracteriza la conducta pública de los cristianos; en Stg 3:17 es marca de la sabiduría de lo alto; en 1 Pe 2:18 describe a los amos bondadosos. Las traducciones amable, gentil y el alemán sanftmütig confirman este núcleo de mansedumbre razonable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67684, 'spa', 'Buscar con fervor, desear con intensidad o perseguir algo de manera persistente', 'Buscar con fervor, desear con intensidad o perseguir algo de manera persistente. Abarca doce de las trece apariciones y comprende tanto la búsqueda encomiable como la reprensible. Los gentiles ''buscan afanosamente'' las necesidades materiales (Mt 6:32; Lc 12:30), los que piden señales ''exigen'' una señal (Mt 12:39; 16:4), y los patriarcas ''buscan'' una patria celestial (He 11:14; 13:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67692, 'spa', 'Buscar a una persona específica con el propósito de localizarla físicamente', 'Buscar a una persona específica con el propósito de localizarla físicamente. En Hechos 12:19, Herodes ''busca'' a Pedro tras su fuga de la prisión, enviando guardias para encontrarlo y recapturarlo. El contexto narrativo restringe el significado a una búsqueda concreta de una persona, aunque léxicamente es idéntico al sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67693, 'spa', 'Condenado a muerte', 'Pablo utiliza una vívida imagen de la arena para describir el ministerio apostólico. Los apóstoles no son celebridades triunfantes sino prisioneros condenados, desfilados ante el cosmos: ángeles, hombres, toda la creación. Esta impactante metáfora socava el sentido de superioridad de los corintios, mostrando que el verdadero servicio apostólico implica sufrimiento y humillación pública, no gloria terrenal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67694, 'spa', 'Imposición de manos', 'La imposición de manos como acto religioso formal de comisión, bendición o transmisión espiritual. Hechos 8:18 describe a Simón observando cómo el Espíritu se otorgaba mediante la imposición de manos de los apóstoles. Pablo recuerda a Timoteo el don conferido ''por la imposición de manos'' del presbiterio (1 Timoteo 4:14) y las suyas propias (2 Timoteo 1:6). Hebreos 6:2 la incluye entre las enseñanzas fundamentales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67695, 'spa', 'Desear, anhelar', 'Desear, anhelar: desear, anhelar o suspirar por algo, con connotación neutra o positiva. Jesús desea ardientemente compartir la Pascua con sus discípulos (Lucas 22:15), profetas y justos anhelaron ver y oír lo que los discípulos experimentan (Mateo 13:17; 1 Pedro 1:12), y el hijo pródigo anhela llenar su estómago incluso con la comida de los cerdos (Lucas 15:16; cf. Lucas 16:21; 17:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67697, 'spa', 'Codiciar, desear pecaminosamente', 'Codiciar, desear pecaminosamente: codiciar, desear con lascivia o ansiar de manera pecaminosa, un deseo dirigido hacia un objeto prohibido. Jesús intensifica el mandamiento: mirar a una mujer «para desearla» ya es adulterio del corazón (Mateo 5:28). Pablo identifica este verbo con el Décimo Mandamiento: «No habría conocido la codicia si la ley no hubiera dicho: No codiciarás» (Romanos 7:7; 13:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67711, 'spa', 'Codiciador de lo malo', 'Pablo identifica a la generación del desierto como «codiciadores de lo malo». Los israelitas murmuraron por la comida de Egipto, cayeron en idolatría e inmoralidad sexual: todo brotó del deseo perverso. Pablo aplica esto tipológicamente: la comunidad bautizada no debe repetir el patrón de Israel de codiciar aquello que conduce al juicio divino. El sustantivo agentivo describe personas caracterizadas por el deseo desenfrenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67712, 'spa', 'deseo pecaminoso o concupiscencia', 'deseo pecaminoso o concupiscencia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67722, 'spa', 'anhelo ferviente o profundo', 'anhelo ferviente o profundo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67726, 'spa', 'Sentarse sobre', 'Mateo registra a Jesús montando el pollino para su entrada triunfal. Este detalle aparentemente sencillo tiene profundo peso profético: el rey entra en Jerusalén no sobre un caballo de guerra sino sobre una humilde bestia de carga, señalando paz en vez de conquista. El verbo marca el momento en que Jesús asume la postura profetizada, cabalgando hacia la ciudad con destino mesiánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67727, 'spa', 'ser llamado o apodado', 'ser llamado o apodado');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67728, 'spa', 'invocar o clamar', 'invocar o clamar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67729, 'spa', 'apelar legalmente', 'apelar legalmente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67746, 'spa', 'Cobertura o pretexto', 'Pedro aborda el posible abuso de la libertad cristiana. El término abarca tanto la cubierta literal como el encubrimiento figurado. La libertad cristiana no es licencia para pecar disfrazadamente. El versículo equilibra dos verdades: vivan como personas libres, pero como siervos de Dios. La libertad no debe convertirse en máscara ni excusa para la malicia, sino manifestarse en servicio justo y obediencia gozosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67747, 'spa', 'Cubrir pecados', 'Pablo cita la bienaventuranza de David sobre el perdón. No se trata de negación ni ignorancia, sino de ocultamiento misericordioso: Dios cubre los pecados para que ya no acusen. La voz pasiva enfatiza la iniciativa divina: Dios actúa para esconder las transgresiones de su propia mirada judicial. Esta imagen veterotestamentaria anticipa la revelación plena de la justificación por gracia mediante la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67748, 'spa', 'Bajo maldición divina', 'Todas las traducciones emplean lenguaje de maldición: maldito, malditos. Juan 7:49 muestra el desprecio de los fariseos: «esta multitud que no conoce la ley es maldita». Gálatas 3:10 cita Deuteronomio: «Maldito todo aquel que no permanece en todas las cosas escritas en la Ley». Gálatas 3:13 declara la inversión del evangelio: «Cristo nos redimió de la maldición de la ley, hecho por nosotros maldición».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67749, 'spa', 'Apremiar, agolparse', 'Presionar, agolparse, apremiar con urgencia, transmitiendo fuerza activa, insistencia o presión abrumadora de personas o circunstancias que se ciernen sobre alguien. Tres apariciones lucanas: la multitud ''agolpándose'' sobre Jesús junto al lago de Genesaret, ansiosa de oír la palabra de Dios (Lc 5:1), las voces de los principales sacerdotes y la multitud ''apremiando'' a Pilato para crucificar a Jesús (Lc 23:23), y la tempestad ''cargando'' sobre los náufragos hasta abandonar toda esperanza (Hch 27:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67750, 'spa', 'Yacer sobre, estar puesto', 'Yacer sobre algo, estar puesto o impuesto, describiendo un objeto físico que reposa sobre otro, o una obligación o regulación establecida sobre alguien. Cuatro apariciones: la piedra ''puesta'' sobre la entrada del sepulcro de Lázaro (Jn 11:38), pescado y pan ''puestos sobre'' brasas en el desayuno junto al lago (Jn 21:9), la necesidad ''impuesta'' a Pablo de predicar (1 Co 9:16), y las regulaciones ceremoniales ''impuestas'' hasta el tiempo de la reforma (Heb 9:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67756, 'spa', 'Filósofo epicúreo', 'Lucas sitúa el sermón de Pablo en el Areópago dentro de un contexto filosófico. Los epicúreos, nombrados por su fundador, habrían considerado absurda la proclamación de la resurrección y la llamada al arrepentimiento irrelevante para su búsqueda de la ataraxia. El mensaje de Pablo sobre un Creador que juzga a la humanidad mediante un hombre resucitado desafiaba frontalmente el atomismo epicúreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67757, 'spa', 'Auxilio divino', 'El testimonio de Pablo ante Agripa resalta la asistencia divina. A través de naufragios, golpes, encarcelamientos y conspiraciones, el auxilio de Dios ha preservado a Pablo para cumplir su vocación apostólica. No se trata de una providencia abstracta, sino de una protección concreta que le permite comparecer ante reyes y continuar proclamando el evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67758, 'spa', 'Sentenciar judicialmente', 'El relato lucano de la pasión capta la capitulación judicial de Pilato. A pesar de no hallar culpa alguna en Jesús, emite la sentencia fatal cediendo ante la presión política. Este verbo marca el momento en que la conveniencia triunfa sobre la justicia, cuando el veredicto de un gobernador romano envía al Hijo de Dios a la cruz para apaciguar a la turba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67759, 'spa', 'Agarrar, asir (físico)', 'Agarrar, asir (físico): aprehensión física o agarre de una persona, típicamente por la mano o el brazo, a menudo con un propósito: sanar, rescatar, guiar o arrestar. Este sentido dominante recorre los Evangelios Sinópticos y Hechos: Jesús agarra la mano de Pedro sobre el agua (Mateo 14:31), toma a un niño y lo pone junto a sí (Lucas 9:47), y se ase de Simón de Cirene para cargar la cruz (Lucas 23:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67763, 'spa', 'Atrapar, tender una trampa (intención hostil)', 'Atrapar, tender una trampa (intención hostil): atrapar o tender una trampa a alguien en el habla con intención adversa. Solo 2 apariciones, ambas en Lucas 20: las autoridades religiosas envían espías «para atraparlo en lo que dijera» (Lucas 20:20), pero «no pudieron atraparlo en palabra alguna ante el pueblo» (Lucas 20:26). El paso de asir físicamente a atrapar verbalmente es sutil pero real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67767, 'spa', 'Echar mano (figurado, espiritual)', 'Echar mano (figurado, espiritual): echar mano de algo abstracto de manera figurada o espiritual, asiendo por fe lo que no se puede tocar. Una aparición clara en 1 Timoteo 6:19, donde Pablo exhorta a los creyentes generosos a «echar mano de lo que verdaderamente es vida». El verbo físico se reutiliza deliberadamente: la misma mano que agarraba cuerpos ahora se extiende hacia lo eterno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67768, 'spa', 'Olvidar, descuidar', 'Perder algo de la memoria o no mantenerlo presente, ya sea por inadvertencia o por elección deliberada. Los discípulos olvidaron (ἐπελάθοντο) traer pan (Mt 16:5; Mc 8:14), un descuido cotidiano; sin embargo, Dios no olvida (ἐπιλαθέσθαι) los actos de amor (Heb 6:10). Pablo en Filipenses 3:13 lo usa para denotar un dejar atrás deliberado del pasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67775, 'spa', 'Faltar o agotarse', 'El autor de Hebreos emplea un recurso retórico para indicar la abundancia de ejemplos. El desfile de testigos fieles de la historia de Israel podría extenderse indefinidamente, pero el autor debe ser selectivo. El tiempo mismo se convierte en un recurso finito, insuficiente para relatar a todos los que vivieron por fe conquistando reinos y cerrando bocas de leones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67776, 'spa', 'Olvido espiritual', 'Santiago usa «oidor de olvido» para describir un compromiso ineficaz con la palabra de Dios. Esta persona oye pero no retiene, como quien se mira al espejo y al instante olvida su propio rostro. La verdadera bendición viene para quien mira con atención y persevera, traduciendo la verdad escuchada en obediencia vivida en lugar de dejarla escapar de la memoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67777, 'spa', 'Tiempo restante', 'Pedro llama a una reorientación radical del tiempo que queda en la vida mortal. Las traducciones multilingües (español «restante», francés equivalente) enfatizan lo que sobra o permanece. Habiendo sufrido en la carne y cesado del pecado, los creyentes deben dedicar el tiempo terrenal que les resta no a los deseos anteriores, sino al propósito de Dios. Es una administración fiel de la mortalidad restante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67778, 'spa', 'Interpretación profética', 'Pedro aborda el origen y la autoridad de la Escritura profética. Las traducciones multilingües (español «interpretación», alemán «Auslegung») captan el sentido explicativo. El punto central es que la profecía no surgió por impulso humano sino por iniciativa divina: el Espíritu movió a hombres santos a proclamar la palabra de Dios. Esto establece la autoridad escritural frente a falsos maestros que reclaman revelaciones privadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67780, 'spa', 'Testimonio apostólico', 'Pedro cierra su carta con una atestación apostólica. El verbo aparece como testificar o dar testimonio en apoyo de la autenticidad del evangelio. El rol de Pedro no es solo exhortar, sino certificar desde su experiencia personal y autoridad apostólica que la gracia proclamada a estos creyentes sufrientes es auténtica. Su testimonio tiene peso como quien caminó con Jesús y fue testigo de la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67781, 'spa', 'Cuidado solícito', 'Lucas destaca el trato humano del centurión hacia su prisionero. Las traducciones multilingües (español «cuidado», francés «soin») convergen en atención y esmero. Julio permite a Pablo visitar a los creyentes en Sidón para que atiendan sus necesidades prácticas. Esta pequeña bondad refleja tanto el carácter del centurión como la providencia divina que asegura el bienestar de Pablo en su camino al juicio en Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67782, 'spa', 'Cuidar, atender', 'Las traducciones emplean consistentemente lenguaje de cuidado: en español «Cuídalo/cuidó», en francés prendre soin. Lucas 10:34 describe al samaritano que «cuidó de» el herido, mientras que 10:35 registra su promesa al mesonero sobre gastos adicionales. Primera Timoteo 3:5 pregunta retóricamente cómo alguien que no sabe gobernar su propia casa podrá cuidar de la iglesia de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67783, 'spa', 'Búsqueda diligente', 'La única aparición en el Nuevo Testamento describe la búsqueda diligente de la mujer en la parábola de Jesús, donde el adverbio enfatiza la minuciosidad y la atención al detalle que ella emplea. Las traducciones interlingüísticas captan uniformemente este sentido de acción cuidadosa y deliberada, reflejando una comprensión consistente de que se trata de la calidad de la atención más que de la mera acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67784, 'spa', 'Permanecer, quedarse en un lugar', 'Permanecer, quedarse en un lugar: quedarse o permanecer en un lugar específico por un período de tiempo, enfatizando la presencia física. Pablo permanece en Cesarea (Hechos 21:10), los viajeros se demoran en Siracusa (Hechos 28:12), Pedro se queda en Jope (Hechos 10:48). La fuerza durativa del prefijo ἐπι- implica una estadía deliberada y prolongada más que una breve parada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67787, 'spa', 'Continuar, persistir en un estado', 'Continuar, persistir en un estado: continuar o persistir en un estado, acción o disposición, enfatizando el compromiso continuo más que la ubicación física. Las preguntas teológicas de Pablo en Romanos —«¿Perseveraremos en el pecado?» (6:1), «permanecer en su bondad» (11:22)— emplean este sentido. En Juan 8:7 Jesús «continuó» preguntando, y en Hechos 12:16 Pedro «continuó» llamando a la puerta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67797, 'spa', 'Consentir o asentir', 'En Hechos 18:20, el verbo describe la posible respuesta de Pablo a la petición de los efesios de permanecer con ellos. La evidencia interlingüística se centra en consentir o estar de acuerdo, ya sea mediante gesto o asentimiento verbal. El uso clásico enfatizaba la inclinación de cabeza como aprobación autoritativa, que evolucionó hacia la idea general de acuerdo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67798, 'spa', 'Intención o propósito', 'La reprensión de Pedro en Hechos 8:22 se enfoca en la intención o propósito subyacente de Simón, el pensamiento detrás de su oferta de comprar poder espiritual. La evidencia interlingüística revela una tensión entre el neutro pensamiento (español/francés) y el moralmente cargado intent (inglés), siendo que el contexto enfatiza claramente la cualidad deliberada y premeditada del estado mental de Simón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67799, 'spa', 'Perjurar o jurar falsamente', 'En el Sermón del Monte (Mateo 5:33), Jesús prohíbe el quebrantamiento de juramentos, aludiendo a la enseñanza judía tradicional contra el perjurio. La consistencia interlingüística --todas las principales lenguas europeas lo traducen como perjurar-- refleja la gravedad universal de las violaciones de juramentos en las culturas mediterráneas. Se oponía a εὐορκέω (cumplir fielmente los juramentos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67800, 'spa', 'Perjuro o quebrantador', 'El catálogo de vicios de Pablo en 1 Timoteo 1:10 sitúa a los perjuros entre ofensores graves contra la ley divina: homicidas, traficantes de esclavos y los sexualmente inmorales. Las glosas interlingüísticas (español perjuros, alemán Meineidige) identifican consistentemente a estas personas como definidas por el quebrantamiento de juramentos, no simples mentirosos ocasionales sino violadores habituales de compromisos solemnes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67801, 'spa', 'El día siguiente', 'El día siguiente, al otro día — marcador temporal que indica el día posterior a un evento previamente mencionado. Usado exclusivamente en Hechos como recurso de transición narrativa. En Hch 7:26 marca el regreso de Moisés; en Hch 16:11, 20:15 y 21:18 rastrea la cronología de viaje de Pablo; en Hch 23:11 introduce la aparición nocturna del Señor. El español ''día siguiente'' confirma el sentido temporal directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67803, 'spa', 'Caer sobre alguien (del Espíritu, el temor u otra fuerza abstracta que desciende', 'Caer sobre alguien (del Espíritu, el temor u otra fuerza abstracta que desciende sobre una persona). De una fuerza invisible o sobrenatural —especialmente el Espíritu Santo o el temor— que desciende repentina y abrumadoramente sobre alguien. Es el verbo característico de la llegada dramática del Espíritu en Hechos (8:16; 10:44; 11:15), y del terror que sobrecoge a Zacarías (Lc 1:12) y a los efesios (Hch 19:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67806, 'spa', 'Caer sobre, abalanzarse (en acción agresiva de multitud)', 'Caer sobre, abalanzarse (en acción agresiva de multitud). Arrojarse o abalanzarse sobre alguien de manera agresiva, en un contexto de multitud. En Mr 3:10, los afligidos ''se abalanzaban'' sobre Jesús para tocarlo, donde el verbo captura la cualidad apremiante, casi violenta, de la desesperación de la multitud por recibir sanidad. Una sola aparición, pero un uso semánticamente distinto del abrazo o del descenso espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67808, 'spa', 'Caer sobre alguien (abrazar físicamente, echarse sobre una persona)', 'Caer sobre alguien (abrazar físicamente, echarse sobre una persona). Echarse sobre el cuerpo de alguien en un abrazo físico que expresa emoción intensa: gozo, dolor o afecto. El padre del hijo pródigo ''se echó sobre su cuello'' (Lc 15:20), transmitiendo vívidamente el peso corporal del reencuentro. Pablo cae sobre Eutico para reanimarlo (Hch 20:10), y los ancianos de Éfeso caen sobre el cuello de Pablo llorando en la despedida (Hch 20:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67811, 'spa', 'Reprender con severidad', 'La instrucción pastoral de Pablo en 1 Timoteo 5:1 emplea este verbo para describir lo que Timoteo debe evitar: una reprensión áspera y severa a los ancianos. Las glosas interlingüísticas enfatizan la cualidad confrontativa: el español reprendas sugiere censura, el alemán zurechtweisen implica enderezar a alguien. El trasfondo clásico muestra una evolución del golpe físico al castigo o corrección verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67812, 'spa', 'Anhelar, desear ardientemente', 'Anhelar a alguien o algo con intensidad profunda y sostenida; sentir un deseo que arde y aprieta el corazón. El prefijo ἐπι- sobre ποθέω (''desear'') señala una intensificación: es un anhelo que envuelve a toda la persona. Pablo lo emplea para expresar su añoranza pastoral por las iglesias que ama (Ro 1:11; Fil 1:8; 2:26; 1 Ts 3:6) y para el gemido escatológico de ser revestido del cuerpo celestial (2 Co 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67822, 'spa', 'Anhelado con afecto', 'La tierna forma en que Pablo se dirige a los filipenses (4:1) como ''anhelados'' expresa su profundo vínculo emocional y su deseo de volver a verlos. La evidencia interlingüística resalta la cualidad afectiva: el español anhelados transmite anhelo, el inglés longed-for sugiere deseo persistente a través de la distancia. La asignación al dominio de Actitudes/Emociones refleja cómo esta palabra funciona para expresar el estado interior del hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67823, 'spa', 'Anhelo persistente', 'La declaración de Pablo en Romanos 15:23 sobre su prolongado anhelo de visitar Roma capta la cualidad sostenida de este sustantivo: no un deseo pasajero sino una aspiración persistente de años. Las glosas interlingüísticas oscilan entre un neutro ''deseo'' (francés) y un más intenso ''anhelo'' (español, inglés), lo que indica que los traductores debaten si enfatizar la intensidad o la duración del sentimiento de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67824, 'spa', 'Acudir hacia un lugar', 'Lucas 8:4 describe a multitudes de diversas ciudades que acuden a Jesús, con este participio sugiriendo un viaje intencionado hacia un destino. Las glosas interlingüísticas revelan decisiones interpretativas: si se enfatiza el viaje en sí o la congregación resultante. El español que-acudían se centra en la convergencia, mientras que el sentido clásico enfatizaba el recorrido. El contexto narrativo apoya la lectura de un movimiento deliberado hacia Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67825, 'spa', 'Coser un remiendo', 'La parábola de Jesús en Marcos 2:21 emplea la imagen práctica de coser un parche sobre un vestido para ilustrar la incompatibilidad teológica entre el vino nuevo y los odres viejos, entre el nuevo pacto y las formas antiguas. La evidencia interlingüística se concentra en la acción básica de coser, con el alemán aufnähen captando específicamente la dimensión de ''sobre''. La asignación al dominio de Asociación puede reflejar cómo este versículo funciona metafóricamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67828, 'spa', 'Provisiones alimenticias', 'En la alimentación de los cinco mil (Lucas 9:12), la preocupación de los discípulos por las provisiones resalta el problema práctico: ¿dónde conseguirá comida esta multitud? La unanimidad interlingüística, donde todos los idiomas principales traducen como ''provisiones'' o ''víveres'', refleja la naturaleza concreta y material de la palabra. El uso clásico que abarca tanto la búsqueda de abastecimiento como las reservas sugiere que se trata de procurar sustento en un contexto de necesidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67829, 'spa', 'Visitar, mirar con cuidado o interés', 'Visitar, mirar con cuidado o interés. Visitar a alguien con gracia, cuidado o propósito redentor, usado tanto de la intervención salvífica de Dios como de actos humanos de misericordia hacia los que sufren. Este sentido dominante (10 ocurrencias) está cargado teológicamente: Zacarías alaba a Dios que ''ha visitado y redimido a su pueblo'' (Lucas 1:68), el amanecer celestial ''nos visitará desde lo alto'' (Lucas 1:78), y las multitudes en Naín glorifican a Dios diciendo que ha visitado a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67836, 'spa', 'Seleccionar, elegir (mediante inspección)', 'Seleccionar, elegir (mediante inspección). Examinar cuidadosamente y seleccionar personas idóneas para una tarea, eligiendo por inspección en lugar de visitar con compasión. Solo 1 ocurrencia clara: Hechos 6:3, donde los apóstoles instruyen a la congregación a ''buscar de entre vosotros siete varones de buen testimonio''. El español buscad y el griego subyacente ἐπι-σκεπ- (''mirar cuidadosamente sobre'') resaltan el elemento de inspección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67837, 'spa', 'Morar protectoramente sobre', 'La declaración de Pablo en 2 Corintios 12:9 transforma el lenguaje del alojamiento militar en una imagen de habitación divina. Las glosas interlingüísticas navegan entre metáforas espaciales (habitar, establecerse) y relacionales (reposar). El contexto sugiere que el poder divino halla su hogar en la vulnerabilidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67838, 'spa', 'Cubrir con sombra divina', 'Hacer sombra sobre, envolver con sombra, especialmente de la presencia divina que cubre, protege o manifiesta su poder. Abarca el sentido literal y el uso teológico del cobijo divino. En la Transfiguración (Matt 17:5; Mark 9:7; Luke 9:34) la nube de gloria cubre a los discípulos; en Luke 1:35 expresa la acción creadora de Dios sobre María.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67840, 'spa', 'Visitación divina', 'Acto de Dios de acercarse para inspeccionar, juzgar o mostrar misericordia. En Lucas 19:44, Jesús llora sobre Jerusalén porque la ciudad ''no reconoció el tiempo de tu visitación'', señalando el momento de la llegada llena de gracia de Dios. Primera Pedro 2:12 anticipa igualmente un ''día de visitación'' en el que los de fuera glorificarán a Dios. El término evoca la tradición hebrea de la intervención divina en la historia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67841, 'spa', 'Supervisor o guardián eclesial', 'Supervisor, obispo, guardián: el encargado de velar por un grupo y dirigirlo, especialmente una congregación cristiana. El sentido clásico griego de ''vigilante'' se traslada al uso eclesial del NT. En Acts 20:28 Pablo equipara este rol con el de pastor; en 1 Pet 2:25 se atribuye a Cristo como supremo guardián de las almas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67842, 'spa', 'Revertir la circuncisión', 'La instrucción de Pablo en 1 Corintios 7:18 aborda una práctica real del siglo primero: hombres circuncidados que buscaban revertir el procedimiento para evitar el estigma social grecorromano. Las glosas interlingüísticas reflejan la práctica cultural específica más que el sentido literal del verbo, priorizando la realidad histórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67843, 'spa', 'Conocer o estar familiarizado con algo o alguien a través de la experiencia, la ', 'Conocer o estar familiarizado con algo o alguien a través de la experiencia, la familiaridad o la competencia reconocida. El espíritu maligno dice ''a Pablo lo conozco'' (ἐπίσταμαι, Hch 19:15), transmitiendo reconocimiento de una autoridad probada más que mera consciencia. Usado a lo largo de Hechos para conocimiento práctico y situacional: Pedro sabe que es ilícito para un judío asociarse con gentiles (Hch 10:28), y Apolos solo conocía el bautismo de Juan (Hch 18:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67846, 'spa', 'Entender o comprender la naturaleza o significado de algo, enfatizando la captac', 'Entender o comprender la naturaleza o significado de algo, enfatizando la captación intelectual más que la familiaridad vivencial. Judas 1:10 advierte que las personas ''injurian lo que no entienden'' (ἐπίστανται), emparejando la ignorancia con la corrupción instintiva. Marcos 14:68 capta la negación de Pedro en pánico: ''Ni sé ni entiendo lo que dices.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67852, 'spa', 'Maestro, supervisor', 'Título de tratamiento respetuoso que significa ''maestro'' o ''supervisor'', usado exclusivamente en el Evangelio de Lucas como forma de dirigirse a Jesús por parte de sus discípulos. En el griego clásico designaba a un superintendente, comandante o persona puesta al frente de otros, una figura de autoridad cívica. Lucas lo selecciona donde los otros sinópticos tienen ''Rabí'' o ''Maestro'', subrayando así la autoridad de Jesús más que su mero papel como enseñante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67853, 'spa', 'Escribir, comunicar por carta', 'Los testimonios multilingües emplean terminología de escritura y envío: en español «escribimos/escribirles», en francés écrire, en alemán schreiben. Hechos 15:20 contiene la decisión del concilio: «que les escribamos que se abstengan de...». Hechos 21:25 hace referencia a la misma carta. Hebreos 13:22 describe la epístola misma: «os he escrito brevemente».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67854, 'spa', 'Entendido y competente', 'Santiago 3:13 empareja esta palabra con ''sabio'', creando una hendíadis donde entendimiento y sabiduría actúan conjuntamente. Las glosas interlingüísticas enfatizan la capacidad cognitiva: el español entendido sugiere a alguien que comprende a fondo, el alemán verständig implica juicio discernidor. El uso clásico mostraba que se trataba de ser diestro o versado en algo, combinando conocimiento con competencia práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67855, 'spa', 'Fortalecimiento espiritual', 'Fortalecer o confirmar a los creyentes en su fe, especialmente mediante visitas de retorno y palabras de ánimo. Todas las apariciones neotestamentarias se concentran en Hechos: Pablo y Bernabé fortaleciendo las almas de los discípulos (14:22), Judas y Silas confirmando a la iglesia de Antioquía (15:32), Pablo fortaleciendo las congregaciones por Siria y Cilicia (15:41), y su recorrido sistemático por Galacia y Frigia afianzando a todos los discípulos (18:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67856, 'spa', 'Comunicación escrita o despacho enviado a destinatarios, abarcando documentos of', 'Comunicación escrita o despacho enviado a destinatarios, abarcando documentos oficiales, correspondencia apostólica y uso figurado. En Hechos designa cartas de autorización (Hch 9:2; 22:5), decretos conciliares (Hch 15:30) y despachos legales (Hch 23:25, 33). Pablo la emplea para referirse a sus propias cartas apostólicas, defendiendo su peso y autoridad (2 Co 10:9-11; 2 Ts 2:2, 15; 3:14, 17; Col 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67860, 'spa', 'Silenciar, amordazar', 'La instrucción de Pablo en Tito 1:11 emplea imágenes del manejo de animales: los falsos maestros deben ser amordazados como bestias peligrosas. La consistencia interlingüística (todos los idiomas enfatizan tapar la boca o silenciar) refleja la contundencia de la directiva paulina y subraya el control de algo potencialmente dañino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67861, 'spa', 'volverse fisicamente, girar en el sitio', 'volverse fisicamente, girar en el sitio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67862, 'spa', 'regresar a un lugar', 'regresar a un lugar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67863, 'spa', 'volverse espiritualmente, arrepentirse', 'volverse espiritualmente, arrepentirse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67864, 'spa', 'hacer que alguien se vuelva', 'hacer que alguien se vuelva');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67889, 'spa', 'Conversión espiritual', 'El relato en Hechos 15:3 usa lenguaje de movimiento físico para describir la transformación espiritual de los gentiles. Las glosas interlingüísticas privilegian el sentido teológico (conversión) sobre el literal (giro), mostrando cómo esta palabra se volvió término técnico cristiano. El trasfondo clásico de barcos virando nos recuerda que la conversión es ante todo un cambio de rumbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67890, 'spa', 'Reunir, congregar (activo)', 'Formas activas que significan ''congregar, reunir, juntar'' personas o criaturas desde lugares dispersos en un solo sitio. La imagen definitoria es el lamento de Jesús sobre Jerusalén: ''cuántas veces quise reunir (ἐπισυναγαγεῖν) a tus hijos, como la gallina reúne a sus polluelos bajo sus alas'' (Mt 23:37; Lc 13:34). El uso escatológico en Mt 24:31 y Mr 13:27 extiende la imagen a escala cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67893, 'spa', 'Ser congregado (pasivo)', 'Formas pasivas que significan ''ser reunido, ser congregado'', describiendo el estado resultante cuando personas convergen en una multitud o asamblea. Mr 1:33 pinta a toda la ciudad ''reunida'' (ἐπισυνηγμένη) a la puerta de Pedro; Lc 12:1 narra a miríadas ''habiéndose congregado'' tan densamente que se pisaban unos a otros; y Lc 17:37 emplea un enigmático proverbio sobre buitres que se congregan donde yace el cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67898, 'spa', 'Convergencia apresurada', 'En Mark 9:25, la repentina convergencia de la multitud hacia Jesús crea urgencia: debe actuar antes de que la escena se intensifique. Las glosas interlingüísticas preservan tanto el movimiento (francés accourir) como la reunión resultante (español reunía). El contexto narrativo sugiere multitudes buscando el espectáculo del exorcismo, con Jesús respondiendo con premura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67900, 'spa', 'Peligroso o precario', 'La nota de Lucas en Acts 27:9 de que la navegación se había vuelto peligrosa marca la transición del verano seguro a las traicioneras tormentas otoñales del Mediterráneo. La unanimidad interlingüística (dangerous, perilous) refleja el riesgo concreto para la vida y la carga. El uso médico clásico nos recuerda que no se trata de inconveniencia sino de amenaza genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67901, 'spa', 'Insistencia vehemente', 'La insistencia de los acusadores ante Pilato (Luke 23:5) escala sus cargos: se vuelven más urgentes y enérgicos al presionar su caso contra Jesús. Las glosas interlingüísticas enfatizan la persistencia (español insistían, francés insister), captando la calidad implacable de su alegato. El sentido clásico de ''fortalecerse'' o ''prevalecer'' sugiere que se trata de intensificación, donde la acusación cobra fuerza progresivamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67902, 'spa', 'Acumular o amontonar', 'La advertencia de Pablo en 2 Timothy 4:3 sobre amontonar maestros usa la imagen de acumulación para criticar el consumismo espiritual: reunir múltiples voces hasta encontrar las que satisfagan los propios deseos. Las glosas interlingüísticas preservan la metáfora de apilar (español amontonarán, alemán aufhäufen), aunque el objeto (maestros) hace claramente figurativo el uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67903, 'spa', 'Mandato', 'Directriz u orden emitida con autoridad vinculante, particularmente de Dios o de un apóstol. Pablo usa este sentido para señalar el origen de su apostolado (''por mandato de Dios nuestro Salvador'', 1 Ti 1:1) y para precisar que ciertas enseñanzas no proceden de mandato divino (1 Co 7:6, 7:25). La convergencia entre idiomas hacia ''mandato'' confirma el carácter imperativo del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67905, 'spa', 'Autoridad', 'El derecho delegado de mandar, pasando del acto de ordenar a la posición de autoridad que lo respalda. En Tito 2:15, Pablo instruye a Tito a ''exhortar y reprender con toda autoridad'' (μετὰ πάσης ἐπιταγῆς), donde la palabra no denota un mandato singular sino la postura autoritativa desde la cual emanan las órdenes. El español ''autoridad'' capta este sentido institucional y continuo, distinguiéndolo del acto puntual de dar una orden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67906, 'spa', 'Mandar, ordenar (con autoridad)', 'Mandar, ordenar (con autoridad). Mandar u ordenar desde una posición de autoridad superior, imponiendo una directiva sobre subordinados, espíritus o fuerzas naturales. Jesús manda a los espíritus inmundos y le obedecen (Marcos 1:27; Lucas 4:36; Marcos 9:25; Lucas 8:31), manda al viento y al agua (Lucas 8:25), y dirige a las multitudes (Marcos 6:39). Las autoridades humanas también lo usan: Herodes ordena la ejecución de Juan (Marcos 6:27), el sumo sacerdote ordena golpear a Pablo (Hechos 23:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67912, 'spa', 'Completar, llevar a término', 'Completar, llevar a término. Llevar una obra, tarea o propósito divino a su cumplimiento; terminar lo que se ha comenzado. Usado para completar la colecta económica (2 Corintios 8:6, 11), la entrega de contribuciones de Pablo a Jerusalén (Romanos 15:28) y la promesa de Dios de acabar la buena obra comenzada en los creyentes (Filipenses 1:6). El español completar y el alemán vollenden enfatizan una consumación activa y deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67914, 'spa', 'Ser completado, ser realizado (pasivo)', 'Ser completado, ser realizado (pasivo). En voz pasiva o media, ser llevado a término, alcanzar cumplimiento o ser perfeccionado. La pregunta retórica de Pablo en Gálatas 3:3 — ''habiendo comenzado por el Espíritu, ¿ahora os perfeccionáis por la carne?'' — usa la pasiva para cuestionar la regresión de los gálatas. En 1 Pedro 5:9, los padecimientos ''se están cumpliendo'' en toda la hermandad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67919, 'spa', 'Realizar, cumplir (deberes religiosos)', 'Realizar, cumplir (deberes religiosos). Ejecutar o llevar a cabo ritos religiosos, deberes sagrados o actos de servicio consagrado. En Hebreos 9:6 los sacerdotes entran en el tabernáculo exterior ''cumpliendo'' sus servicios rituales; en 2 Corintios 7:1 se exhorta a los creyentes a perfeccionar la santidad en el temor de Dios. El español distingue entre ''cumplir'' (realizar deberes) y ''perfeccionar'' (perfeccionar la santidad), captando el doble matiz de ejecución ritual y refinamiento espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67921, 'spa', 'Necesario o indispensable', 'James 2:16 resalta la amarga ironía de desearle bienestar a alguien sin proveer lo necesario: cosas indispensables como alimento y vestido que el amor encarnado suministraría. Las glosas interlingüísticas enfatizan la cualidad de requerido o necesario: no son lujos sino necesidades genuinas. El uso clásico de ''apto para un propósito'' nos recuerda que lo necesario es también lo apropiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67922, 'spa', 'poner o colocar sobre', 'poner o colocar sobre');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67931, 'spa', 'anadir, imponer ademas', 'anadir, imponer ademas');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67939, 'spa', 'agredir, atacar', 'agredir, atacar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67944, 'spa', 'El sentido principal (28 veces)', 'El sentido principal (28 veces): reprender, censurar o reprochar severamente, generalmente desde una posición de autoridad. Jesús reprende la tormenta (Mt 8:26), a los demonios (Mt 17:18) y al propio Pedro (Mr 8:33). Los discípulos reprenden a quienes traen niños (Mt 19:13), y las multitudes reprenden a los ciegos que claman por misericordia (Mt 20:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67950, 'spa', 'Un sentido matizado (1 vez en Mt 12', 'Un sentido matizado (1 vez en Mt 12:16): advertencia severa o mandato solemne, donde el énfasis se desplaza de la desaprobación por una conducta pasada a una directiva sobre una acción futura. Tras sanar a muchos, Jesús les advierte severamente que no lo den a conocer. La fuerza del verbo se canaliza aquí hacia ordenar silencio, no hacia un reproche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67955, 'spa', 'Castigo correctivo eclesial', 'La referencia de Pablo en 2 Corintios 2:6 a la disciplina eclesiástica emplea esta palabra para el castigo correctivo que la comunidad impuso al ofensor, una pena suficiente para provocar arrepentimiento. Los equivalentes multilingües (castigo, reprensión, punición) reflejan la naturaleza restauradora de esta autoridad disciplinaria, no meramente punitiva sino orientada a la reconciliación del ofensor con la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67956, 'spa', 'Permitir, autorizar', 'Permitir, autorizar: conceder permiso o autorización para una acción, ya sea por autoridad divina, civil o social. Jesús permite a los demonios entrar en los cerdos, demostrando poder soberano sobre lo inmundo (Mateo 8:31; Marcos 5:13; Lucas 8:32). Los diálogos de discipulado giran en torno a lo que Jesús permite antes de seguirle (Mateo 8:21; Lucas 9:59, 61). El «permitir» de Moisés respecto al divorcio se convierte en contraste con el estándar superior de Jesús (Mateo 19:8; Marcos 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67965, 'spa', 'Comisión delegada oficial', 'El testimonio de Pablo en Hechos 26:12 sobre su comisión de los principales sacerdotes subraya la autoridad oficial que respaldaba su misión persecutoria: no era un agente independiente sino un representante autorizado con plenos poderes. Los equivalentes multilingües (comisión, commission, permission) reflejan la naturaleza delegada de esta autoridad, donde Pablo portaba la autorización del sumo sacerdote como representante oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67966, 'spa', 'Mayordomo, administrador', 'Las traducciones emplean lenguaje de mayordomía: en español «mayordomo/tutores», en francés tuteur. Mateo 20:8 presenta al dueño de la viña diciendo a «su mayordomo» que pague a los obreros. Lucas 8:3 identifica a Juana como esposa de «Chuza, administrador de Herodes». Gálatas 4:2 describe al niño que permanece «bajo tutores y administradores» hasta el tiempo señalado por el padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67967, 'spa', 'Obtener o alcanzar', 'Obtener, alcanzar, lograr con éxito: adquirir lo que se buscaba o había sido prometido. El sentido clásico de ''dar en el blanco'' subyace al uso metafórico de alcanzar una meta. En Rom 11:7 aparece en contraste: Israel no obtuvo, pero los elegidos sí. En Heb 6:15 y Heb 11:33 describe la obtención de las promesas divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67968, 'spa', 'Manifestación visible', 'Aparecer, hacerse visible o resplandecer, abarcando tanto la visibilidad física como la manifestación divina. Lucas 1:79 lo emplea para la luz mesiánica que alumbra a los que están en tinieblas. Hechos 27:20 describe la ausencia física de los astros durante una tormenta. En Tito 2:11 y 3:4 el verbo alcanza su mayor peso teológico: la gracia de Dios se ha manifestado a todos los hombres, dando origen al concepto de ''epifanía''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67969, 'spa', 'Aparición, manifestación', 'La manifestación visible y gloriosa de Cristo, abarcando tanto su primer advenimiento (encarnación) como su retorno esperado. En 2 Ti 1:10 se refiere retrospectivamente a la aparición histórica que abolió la muerte, mientras que en 2 Ts 2:8, 1 Ti 6:14 y 2 Ti 4:1, 8 mira hacia una aparición futura en poder. El término transmite el esplendor visible y la majestuosidad de la presencia divina irrumpiendo en la historia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67971, 'spa', 'Glorioso y manifiesto', 'El sermón de Pedro en Pentecostés (Hechos 2:20) cita la profecía de Joel sobre el día del Señor como ''grande y glorioso'', sugiriendo tanto la manifestación dramática como su esplendor. La variación multilingüe (glorioso, manifiesto, notable) refleja la doble carga semántica: algo que aparece de manera impresionante y resulta magnífico, con ecos de epifanías divinas clásicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67972, 'spa', 'Iluminación espiritual', 'El fragmento hímnico de Efesios 5:14 promete que Cristo brillará sobre quienes despierten de la muerte espiritual: la luz inundando a quien se levanta de la oscuridad. La unanimidad multilingüe (brillar, iluminar, alumbrar) refleja la directa metáfora fotológica. La forma pasiva sugiere que la luz alcanza activamente al receptor, presentando a Cristo como sol que amanece sobre quien duerme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67974, 'spa', 'Clamor público', 'Gritar con fuerza en un entorno público, especialmente como multitud que responde a un orador o acontecimiento. Se emplea para los gritos hostiles que exigen la crucifixión (Lc 23:21), para la aclamación de Herodes como ser divino (Hch 12:22) y para el clamor confuso de la turba donde los oficiales no logran discernir la acusación (Hch 21:34, 22:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67976, 'spa', 'Intentar, emprender', 'La evidencia de las traducciones muestra lenguaje de emprendimiento: en español «intentaron/emprendieron», en francés entreprendre. Lucas 1:1 abre el Evangelio: «muchos han emprendido la tarea de componer un relato», estableciendo el método histórico cuidadoso de Lucas. Hechos 9:29 describe a quienes «intentaron» matar a Saulo tras su conversión. Hechos 19:13 narra a exorcistas itinerantes que «intentaban» invocar el nombre de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67977, 'spa', 'Derramar sobre heridas', 'La acción del buen samaritano en Lucas 10:34 de derramar aceite y vino sobre las heridas demuestra un cuidado médico práctico: el aceite calmaba y el vino desinfectaba. Los equivalentes multilingües enfatizan el movimiento y la dirección: derramar-sobre, verser-sur, capturando la aplicación de líquido sobre heridas. El trasfondo clásico incluye usos metafóricos como derramar sueño o lamentos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67978, 'spa', 'Proveer abundantemente', 'Proveer, suplir, suministrar con generosidad: dar abundantemente o añadir a lo que ya existe. Su trasfondo en el mecenazgo cívico (financiar un coro) le confiere matices de liberalidad. En 2 Cor 9:10 Dios suministra semilla y pan; en Gal 3:5 el Espíritu es provisto por la fe. Col 2:19 lo aplica a Cristo que nutre a su cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67981, 'spa', 'Edificar sobre, sobreedificar', 'Edificar sobre un fundamento existente, usado exclusivamente en contextos metafóricos y espirituales en el NT para describir la obra de edificación sobre los cimientos que Dios o sus apóstoles ya han puesto. La extensa metáfora constructiva de Pablo en 1 Corintios 3:10-14 es el pasaje clásico: él puso el fundamento y otros edifican sobre él, pero la calidad de la obra de cada uno será probada por fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67986, 'spa', 'Encallar o varar', 'El clímax del viaje marítimo de Pablo (Hechos 27:41) ocurre cuando el barco choca contra un arrecife o banco de arena, encallando violentamente. Los glosas en distintas lenguas mantienen la precisión náutica: todos los idiomas emplean términos marítimos para describir el varamiento. El contexto describe la proa fija mientras la popa se destroza bajo la fuerza del oleaje, cuadro clásico de un navío atrapado entre fuerzas opuestas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67987, 'spa', 'Llamarse o autodesignarse', 'La interpelación de Pablo en Romanos 2:17 a quienes se llaman judíos plantea la cuestión de la identidad auténtica frente a la nominal. Las glosas multilingües debaten la agencia: el énfasis recae en la autodesignación (tú te llamas) o en la identidad reconocida (eres llamado). El contexto sugiere que Pablo cuestiona si el nombre corresponde a la realidad, pues llamarse judío solo importa si la vida lo refleja.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67989, 'spa', 'Testigo ocular', 'La afirmación de Pedro en 2 Pedro 1:16 de ser testigo ocular fundamenta la autoridad apostólica en la experiencia directa: ellos vieron la gloria de Cristo con sus propios ojos en el monte santo. La unanimidad multilingüe refleja la fuerza forense y testimonial de esta palabra: no son relatos de segunda mano sino evidencia visual de primera mano. El trasfondo clásico en las religiones mistéricas añade matices de visión privilegiada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67990, 'spa', 'Palabra o expresión', 'La frase en Hebreos 7:9 emplea esta palabra dentro de un modismo fijo, ὡς ἔπος εἰπεῖν, ''por así decirlo'', para introducir la audaz afirmación de que Leví pagó diezmos a través de Abraham. Las glosas multilingües (word, palabra) captan el significado léxico básico, aunque los traductores reconocen que la frase funciona idiomáticamente. El uso clásico para oráculos, promesas y cantos muestra que esta palabra frecuentemente portaba un peso formal o solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67991, 'spa', 'Celestial, del cielo', 'Celestial, del cielo: perteneciente al cielo o al ámbito celeste, usado tanto atributiva como sustantivamente. Pablo contrasta cuerpos celestiales y terrenales en la teología de la resurrección (1 Corintios 15:40, 48-49). Efesios desarrolla «los celestiales» (τὰ ἐπουράνια) como un dominio espiritual multidimensional: sede de la autoridad de Cristo, posición de los creyentes y arena de guerra espiritual (Efesios 1:3, 20; 2:6; 6:12). Hebreos lo aplica a la vocación, el don y el santuario celestiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67997, 'spa', 'siete', 'El número cardinal siete, usado en el Nuevo Testamento tanto para contar literalmente como para simbolizar la totalidad y perfección divinas. Aparece en los siete panes (Mt 15:36) y domina Apocalipsis con siete iglesias, sellos, trompetas y copas. Su traducción es uniforme: «siete», «sept», «sieben».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67999, 'spa', 'Siete veces', 'Adverbio numérico que expresa repetición siete veces. En Mateo 18:21-22, Pedro propone perdonar ''siete veces'' como gesto generoso, pero Jesús lo amplía a setenta y siete (o setenta veces siete), transformando el adverbio en símbolo de gracia ilimitada. Lucas 17:4 lo emplea dos veces para describir a un hermano que peca y se arrepiente siete veces en un solo día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68000, 'spa', 'Siete mil', 'La declaración divina de siete mil israelitas fieles (Romanos 11:4, citando 1 Reyes 19) ofrece consuelo teológico a Elías: no está solo, existe un remanente sustancial. La unanimidad multilingüe refleja cómo funcionan los números en la traducción: siete mil es siete mil en todos los idiomas. El peso teológico proviene del papel de este número en la doctrina del remanente: una minoría significativa preservada por la gracia de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68001, 'spa', 'Dijo, habló', 'En todas las lenguas se traduce como pasado simple de habla: «dijo» en español, dire en francés, sprach en alemán. Hechos 8:37 (en los manuscritos que lo incluyen) recoge la confesión del eunuco etíope tras la explicación de Felipe. Hechos 9:5 registra la pregunta de Jesús resucitado a Saulo en el camino a Damasco: «dijo: ¿Quién eres, Señor?». Estos usos muestran la función narrativa estándar de introducir discurso directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68002, 'spa', 'Nombre propio cristiano', 'El nombre aparece de forma uniforme en las traducciones: Erastos, Erastus, Erasto. Hechos 19:22 menciona que Pablo envió a «Timoteo y Erasto» a Macedonia como colaboradores ministeriales. Romanos 16:23 incluye saludos de «Erasto, tesorero de la ciudad», señalándolo como creyente con responsabilidad cívica. 2 Timoteo 4:20 indica que «Erasto se quedó en Corinto». Si se trata de uno, dos o tres individuos sigue siendo debatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68003, 'spa', 'trabajar, obrar, fatigarse', 'trabajar, obrar, fatigarse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68006, 'spa', 'hacer, realizar, cometer obras', 'hacer, realizar, cometer obras');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68009, 'spa', 'negociar, invertir', 'negociar, invertir');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68014, 'spa', 'producir, causar', 'producir, causar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68021, 'spa', 'ser obrado, haber sido realizado', 'ser obrado, haber sido realizado');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68033, 'spa', 'Ganancia o lucro', 'Ganancia o beneficio derivado de una empresa comercial. En Hechos 16:16 y 16:19 designa los ingresos que la adivinación de una esclava generaba para sus amos, y en Hechos 19:24 se refiere a los considerables réditos que producía el oficio de Demetrio con los templetes de plata. El énfasis recae sobre el rendimiento económico, no sobre el trabajo en sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68034, 'spa', 'Práctica o ejercicio', 'La práctica activa o el ejercicio sostenido de algo, extendido del oficio manual a la conducta moral. En Efesios 4:19, Pablo describe a los gentiles que se entregaron a la ἐργασία de la impureza, donde el sentido es el de una dedicación deliberada y continua a una actividad, no un acto aislado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68035, 'spa', 'Esfuerzo o diligencia', 'Esfuerzo o diligencia aplicados para lograr un resultado concreto. En Lucas 12:58 se insta al oyente a ''poner empeño'' (δὸς ἐργασίαν, eco del latín da operam) para librarse de su adversario de camino al magistrado. El foco está en la exigencia del empeño, no en el comercio ni la ganancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68036, 'spa', 'Negocio u oficio', 'Un oficio, negocio o actividad comercial vista como ocupación habitual. En Hechos 19:25 Demetrio reúne a quienes dependen del mismo ramo de trabajo. El matiz ocupacional distingue este sentido del enfoque puramente monetario del sentido 1, subrayando el sustento y la identidad profesional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68037, 'spa', 'Obrero, trabajador', 'Obrero, trabajador: persona que realiza trabajo, usado en todo el NT para trabajadores agrícolas en la imaginería de la cosecha (Mateo 9:37-38; 20:1-8; Lucas 10:2), ministros del evangelio y misioneros (2 Corintios 11:13; 2 Timoteo 2:15; Filipenses 3:2), y practicantes genéricos de obras buenas o malas (Lucas 13:27 «obreros de iniquidad»; Hechos 19:25 artesanos). La declaración de Jesús de que «el obrero es digno de su salario» (Mateo 10:10; Lucas 10:7) se convirtió en principio fundacional para el sustento ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68043, 'spa', 'hecho o acción', 'Un hecho, acto o conducta considerada especialmente en su dimensión moral o espiritual. Es el uso neotestamentario dominante, que abarca las ''obras de la ley,'' las ''buenas obras'' y las ''malas obras.'' Juan 3:19-21 presenta la división moral con máxima nitidez: los que hacen el mal odian la luz, pero el que practica la verdad viene a la luz para que sus obras sean manifiestas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68048, 'spa', 'trabajo o tarea', 'Una tarea, empresa o labor emprendida, con el sentido de trabajo productivo más que de evaluación moral. En Romanos 2:7, la ''perseverancia en bien obrar'' se orienta hacia el esfuerzo y la constancia; Filipenses 1:22 habla de ''labor fructífera'' como empresa en curso. Santiago 1:25 tiende un puente entre ambos sentidos, donde el ''hacedor de la obra'' implica tanto acción ética como esfuerzo sostenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68056, 'spa', 'Encallar o quedar clavado', 'En Hechos 27:41, la proa queda clavada en el banco de arena mientras las olas destrozan la popa. Los glosarios interlingüísticos oscilan entre fijeza general (atascado) y lo náutico específico (encallado), mientras que el español clavado captura vívidamente la imagen del barco empalado en el arrecife.');